import './style.css';
import {Game,BIOMES} from './game.js';
import {HEROES,MONSTERS,branchEffect,VERSION} from './roster.js';
import {ACTIVE_SKILLS,ARMORY,ARMORY_COSTS,MASTERY_COSTS,RELICS} from './content.js';
import {Scene} from './scene.js';
import {Input} from './input.js';
import {readProgress,saveProgress,buyArmory,buyMastery} from './progress.js';
import {api,metric,ads} from './services.js';
import {AudioSys} from '../core/AudioSynth.js';

const $=id=>document.getElementById(id),progress=readProgress();
let game,scene,hero=HEROES[progress.selected]?progress.selected:'cinder',runToken=null,settled=false,lastFocus,toastTimer;
function save(){if(!saveProgress(progress))toast('Progress cannot be saved on this device.');}
function toast(text){$('toast').textContent=text;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3500);}
function on(id,fn){$(id)?.addEventListener('click',fn);}
function modal(title,html){lastFocus=document.activeElement;$('modal-title').textContent=title;$('modal-body').innerHTML=html;$('modal').hidden=false;$('modal-body').querySelector('button')?.focus();}
function close(){$('modal').hidden=true;lastFocus?.focus?.();}
function initials(name){return name.split(' ').map(word=>word[0]).join('');}
function updateMenu(){$('banked-gold').textContent=`${progress.gold.toLocaleString()} gold`;$('records').hidden=progress.runs===0;}
function applyAudio(){AudioSys.init();AudioSys.setMix({...progress.audio,master:progress.muted?0:progress.audio.master});}
function select(id){hero=id;progress.selected=id;const h=HEROES[id];$('selected-name').textContent=h.name;$('portrait-caption').textContent=`LIVE 3D MODEL / ${h.name} / ${h.weapon}`;document.documentElement.style.setProperty('--selected-hero',h.color);save();updateMenu();}
select(hero);
try{scene=new Scene($('world'));}catch(e){$('start').disabled=true;toast('WebGL is unavailable. Enable hardware acceleration.');console.error(e);}

function heroes(){modal('Eight souls. Eight oaths.',`<p class="muted">Select a hero to place their live 3D model in the cathedral showcase. Complete expeditions to awaken the remaining oaths.</p><div class="hero-grid">${Object.values(HEROES).map(h=>`<button class="hero-card ${h.id===hero?'selected':''}" data-hero="${h.id}" style="--hero-color:${h.color}" ${progress.runs<h.unlockRuns?'disabled':''}><div class="model-crest"><span>${initials(h.name)}</span></div><h3>${h.name}</h3><p>${h.trait}</p><small>${progress.runs<h.unlockRuns?`Complete ${h.unlockRuns} expeditions (${progress.runs}/${h.unlockRuns})`:h.weapon}</small></button>`).join('')}</div><button id="back">Return</button>`);document.querySelectorAll('[data-hero]').forEach(b=>b.onclick=()=>{select(b.dataset.hero);close();});on('back',close);}
on('heroes',heroes);

function armory(){const mastery=progress.mastery[hero]||0;modal('The Ember Armory',`<div class="armory-head"><p>Recovered gold strengthens every unranked descent. Ranked challenges ignore these bonuses.</p><strong>${progress.gold.toLocaleString()} GOLD</strong></div><h3>Shared forge</h3><div class="armory-grid">${Object.entries(ARMORY).map(([id,item])=>{const rank=progress.armory[id]||0,cost=ARMORY_COSTS[rank];return `<button class="armory-card" data-armory="${id}" ${rank>=item.max||progress.gold<cost?'disabled':''}><small>RANK ${rank} / ${item.max}</small><h3>${item.name}</h3><p>${item.desc}</p><span>${rank>=item.max?'MASTERED':`${cost} gold`}</span></button>`;}).join('')}</div><h3>${HEROES[hero].name} mastery</h3><div class="mastery-card"><p>${mastery===0?'+4% weapon damage':mastery===1?'-5% active-skill cooldown':mastery===2?'+10 starting signature charge and mastery aura':'All mastery oaths fulfilled.'}</p><button id="mastery-buy" ${mastery>=3||progress.gold<MASTERY_COSTS[mastery]?'disabled':''}>${mastery>=3?'Mastered':`Awaken rank ${mastery+1} · ${MASTERY_COSTS[mastery]} gold`}</button></div><button id="back">Return</button>`);document.querySelectorAll('[data-armory]').forEach(b=>b.onclick=()=>{if(buyArmory(progress,b.dataset.armory)){save();armory();}});on('mastery-buy',()=>{if(buyMastery(progress,hero)){save();armory();}});on('back',()=>{updateMenu();close();});}
on('armory',armory);

function settings(returnToPause=false){const slider=(id,label)=>`<label class="volume-setting"><span>${label}</span><input type="range" id="${id}" min="0" max="1" step=".05" value="${progress.audio[id]}"><output>${Math.round(progress.audio[id]*100)}</output></label>`;modal('Sound & accessibility',`<div class="settings-grid"><div><h3>Original procedural audio</h3><p class="muted">Music and effects are generated live in your browser. No recordings or copyrighted samples are used.</p>${slider('master','Master')}${slider('music','Music')}${slider('sfx','Combat effects')}${slider('ambience','Cathedral ambience')}<label class="setting"><input type="checkbox" id="sound" ${progress.muted?'':'checked'}> Audio enabled</label></div><div><h3>Display & controls</h3><label class="setting"><input type="checkbox" id="motion" ${progress.reduced?'checked':''}> Reduce motion</label><p class="muted">WASD / arrows: move<br>Q / E: smart-target skills · R: signature<br>Space: dodge · B / Tab: build · Escape: pause</p><button id="fullscreen">Fullscreen</button></div></div><button id="back">Return</button>`);for(const id of ['master','music','sfx','ambience'])$(id).oninput=e=>{progress.audio[id]=Number(e.target.value);e.target.nextElementSibling.value=Math.round(progress.audio[id]*100);applyAudio();save();};$('sound').onchange=e=>{progress.muted=!e.target.checked;applyAudio();save();};$('motion').onchange=e=>{progress.reduced=e.target.checked;save();};on('fullscreen',()=>document.documentElement.requestFullscreen?.().catch(()=>toast('Fullscreen unavailable.')));on('back',()=>{if(returnToPause&&game?.state==='paused'){game.state='playing';pause();}else close();});}
on('settings',()=>settings());

async function start(kind='solo'){if(!scene)return;$('start').disabled=true;try{let challenge;if(kind!=='solo'){challenge=await api('start',{kind});if(challenge.version!==VERSION)throw new Error('Challenge version is unavailable.');}runToken=challenge?.token||null;game=new Game({hero:challenge?.hero||hero,seed:challenge?.seed??crypto.getRandomValues(new Uint32Array(1))[0],ranked:!!challenge,modifier:challenge?.modifier,meta:progress});settled=false;close();$('menu').hidden=true;$('hud').hidden=false;document.body.classList.add('playing');applyAudio();AudioSys.setScene('exploration');metric('run_start');}catch(e){toast(e.message);}finally{$('start').disabled=false;}}
on('start',()=>start());
function settle(){if(!game||settled)return;settled=true;if(['dead','victory'].includes(game.state)||game.time>=60)progress.runs++;progress.gold+=game.gold;progress.totalKills+=game.kills;progress.bossKills+=game.bossKills;progress.records.push({version:VERSION,hero:game.hero,duration:Math.floor(game.time),kills:game.kills,gold:game.earned,score:game.score(),victory:game.state==='victory'});progress.records.sort((a,b)=>b.score-a.score);progress.records=progress.records.slice(0,10);save();}
function menu(){settle();game=null;close();$('menu').hidden=false;$('hud').hidden=true;document.body.classList.remove('playing');updateMenu();if(AudioSys.ctx)AudioSys.setScene('menu');}
function resume(){close();game.state='playing';AudioSys.setScene(game.enemies.some(e=>e.boss)?'boss':'exploration');}
function confirmQuit(){modal('Abandon this expedition?',`<p>Your recovered run gold will be banked, but this descent will end.</p><div class="row"><button id="cancel" class="primary">Continue fighting</button><button id="confirm-quit" class="danger">Abandon expedition</button></div>`);on('cancel',()=>{game.state='playing';pause();});on('confirm-quit',menu);}
function pause(){if(!game||game.state!=='playing')return;game.state='paused';AudioSys.setScene('menu');const p=game.player;modal('Expedition paused',`<div class="pause-layout"><div class="pause-hero"><small>${BIOMES[game.biome].name}</small><h3>${HEROES[game.hero].name}</h3><p>${HEROES[game.hero].weapon}</p><div class="pause-stats"><strong>${formatTime(game.time)}<span>TIME</span></strong><strong>${game.kills}<span>SLAIN</span></strong><strong>${Math.ceil(p.hp)} / ${p.maxHp}<span>VITALITY</span></strong><strong>${game.gold}<span>GOLD</span></strong></div></div><div class="pause-actions"><button id="resume" class="primary">Resume expedition <span>ESC</span></button><button id="build">Inspect build</button><button id="pause-settings">Sound & accessibility</button><button id="quit" class="danger">Return to camp</button></div></div>`);on('resume',resume);on('build',build);on('pause-settings',()=>settings(true));on('quit',confirmQuit);}
function build(){if(!game||!['playing','paused'].includes(game.state))return;game.state='paused';const h=HEROES[game.hero],skills=ACTIVE_SKILLS[game.hero],relics=Object.keys(game.player.relics);modal(`${h.name} / Your build`,`<p>${h.weapon} · ${h.trait}</p><div class="skill-summary">${skills.map((s,i)=>`<div><small>${i?'E':'Q'} ACTIVE</small><strong>${s.name}</strong><span>${s.desc}</span></div>`).join('')}</div><div class="cards">${h.branches.map((name,i)=>`<div class="card"><small>BRANCH ${i+1} / ${game.player.ranks[i]} OF 3</small><h3>${name}</h3><p>${branchEffect(h.id,i,game.player.ranks[i])}</p><div class="ranks">${[1,2,3].map(n=>`<span class="${game.player.ranks[i]>=n?'lit':''}">${n}</span>`).join(' → ')}</div></div>`).join('')}</div><p class="muted">Relics: ${relics.length?relics.map(id=>RELICS[id]?.name).join(' · '):'None yet'}<br>Damage: ${Object.entries(game.damageLog).map(([k,v])=>`${k} ${Math.round(v).toLocaleString()}`).join(' · ')}</p><button id="resume" class="primary">Return to battle</button>`);on('resume',resume);}
function level(){modal(`Level ${game.player.level} / Choose your path`,`<p class="muted">Each branch has three ranks. The third transforms its effect.</p><div class="cards">${game.choices.map((c,i)=>`<button class="card upgrade" data-choice="${c.id}"><small>${i+1} / RANK ${c.rank+1} OF ${c.max}</small><h3>${c.name}</h3><p>${c.desc}</p><span>${c.connection}</span></button>`).join('')}</div>`);document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{if(game.upgrade(b.dataset.choice))close();});}
function merchant(){const offers=game.merchantOffers;modal('The Reliquary Merchant',`<div class="merchant-head"><p>One relic may follow you into the next sanctuary.</p><strong>${game.gold} RUN GOLD</strong></div><div class="cards">${offers.map(id=>{const r=RELICS[id];return `<button class="card merchant-card" data-relic="${id}" ${game.gold<r.cost?'disabled':''}><small>${r.cost} GOLD</small><h3>${r.name}</h3><p>${r.desc}</p><span>Run relic · lost after the expedition</span></button>`;}).join('')}</div><div class="row"><button id="reroll" ${game.merchantRerolled||game.gold<5?'disabled':''}>Reroll · 5 gold</button><button id="skip">Continue without a relic</button></div>`);document.querySelectorAll('[data-relic]').forEach(b=>b.onclick=()=>{if(game.buyMerchant(b.dataset.relic)){close();toast(`${RELICS[b.dataset.relic].name} bound to your ember.`);}});on('reroll',()=>{if(game.rerollMerchant())merchant();});on('skip',()=>{game.skipMerchant();close();});}
async function finish(victory){settle();const duration=Math.floor(game.time),token=runToken;runToken=null;metric('run_complete');modal(victory?'The last light endures':'The ember remembers',`<p>${victory?'Three guardians have fallen. The sanctuaries are silent.':'Every descent teaches you something.'}</p><div class="statline"><strong>${formatTime(game.time)}<small>SURVIVED</small></strong><strong>${game.kills}<small>SLAIN</small></strong><strong>${game.score().toLocaleString()}<small>SCORE</small></strong></div><p class="muted">${game.earned} gold found · ${game.spent} spent · ${game.gold} recovered</p><p id="upload-status"></p><button id="again" class="primary">Descend again</button><button id="return">Return to camp</button>${!game.ranked&&ads.available()?'<button id="reward">Watch an ad · recover 50 gold</button>':''}`);on('again',()=>start());on('return',menu);let rewardPending=false;on('reward',async()=>{if(rewardPending)return;rewardPending=true;$('reward').disabled=true;if(await ads.reward()){progress.gold+=50;save();$('reward').textContent='50 gold recovered';}else{rewardPending=false;$('reward').disabled=false;}});if(token){const target=$('upload-status');try{await api('submit',{token,duration,kills:game.kills,gold:game.earned,victory});target.textContent='Challenge recorded.';}catch(e){target.textContent=`Score not submitted: ${e.message}`;}}if(!game?.ranked)ads.interstitial(duration,victory);}
async function records(kind='local'){modal('Expedition records',`<div class="row"><button id="local">This device</button><button id="daily">Daily</button><button id="weekly">Weekly</button></div><p id="board-status"></p><div id="record-list"></div><button id="back">Return</button>`);on('back',close);on('local',()=>records());on('daily',()=>records('daily'));on('weekly',()=>records('weekly'));const target=$('record-list'),status=$('board-status');try{const rows=kind==='local'?progress.records:(await api(`board&kind=${kind}`)).records;status.textContent=kind==='local'?`${progress.runs} expeditions · ${progress.gold} gold banked`:'Same hero and seed for every challenger. Armory bonuses are disabled.';for(const r of rows){const p=document.createElement('p');p.textContent=`${HEROES[r.hero]?.name||'Unknown'} · ${formatTime(r.duration)} · ${r.score} points`;target.appendChild(p);}if(kind!=='local'){const b=document.createElement('button');b.textContent=`Play ${kind} challenge`;b.onclick=()=>start(kind);target.appendChild(b);}}catch(e){status.textContent=e.message;}}
on('records',()=>records());

let input;
function action(name,value){if(name==='fullscreen'){document.documentElement.requestFullscreen?.();return;}if(!game)return;if(name==='pause'){if(game.state==='playing')pause();else if(game.state==='paused')resume();}if(name==='autopause')pause();if(name==='dash'){const v=input.vector();game.dash(v.x,v.z);}if(name==='skill')game.useSkill(value);if(name==='ultimate')game.ultimate();if(name==='shop')build();if(name==='choice'&&game.state==='upgrade'){const c=game.choices[value];if(c&&game.upgrade(c.id))close();}}
input=new Input(action);document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));
document.addEventListener('keydown',e=>{if(e.key!=='Tab'||$('modal').hidden)return;const els=[...$('modal').querySelectorAll('button:not(:disabled),input,select')],first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus?.();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus?.();}});
function formatTime(s){return `${Math.floor(s/60).toString().padStart(2,'0')}:${Math.floor(s%60).toString().padStart(2,'0')}`;}
function cooldownLabel(skill,value,key){return value>0?`${skill.name} ${value.toFixed(1)}s`:`${skill.name} [${key}]`;}
function hud(){const p=game.player,skills=ACTIVE_SKILLS[game.hero];$('realm').textContent=BIOMES[game.biome].name;$('time').textContent=formatTime(game.time);$('totals').textContent=`${game.kills} / ${game.gold}`;$('health-label').textContent=`VITALITY ${Math.ceil(p.hp)} / ${p.maxHp}`;$('health').max=p.maxHp;$('health').value=p.hp;$('shield-label').textContent=p.shield>0?`WARD ${Math.ceil(p.shield)}`:'WARD EMPTY';$('shield').max=Math.max(1,p.maxHp);$('shield').value=p.shield;$('level').textContent=`LEVEL ${p.level} / ${Math.floor(p.xp)} OF ${p.need} SOULS`;$('xp').value=p.xp/p.need;$('skill-0').textContent=cooldownLabel(skills[0],p.skills[0],'Q');$('skill-1').textContent=cooldownLabel(skills[1],p.skills[1],'E');$('ultimate').textContent=p.ult>=100?`${HEROES[game.hero].ultName} [R]`:`Signature ${Math.floor(p.ult)}%`;$('dash').textContent=p.stamina>=p.dashCost?'Dodge [Space]':'Recovering';const boss=game.enemies.find(e=>e.boss);$('boss').hidden=!boss;if(boss){$('boss-hp').value=boss.hp/boss.maxHp;$('boss-name').textContent=`${MONSTERS[boss.type].name} / Phase ${boss.phase}`;}$('guide').textContent=progress.runs===0?(game.time<10?'Move with WASD. Your weapon attacks automatically.':game.time<22?'Press Q or E to smart-target dangerous enemies. Dodge with Space.':game.time<35?'Watch enemy windups, then move before the strike lands.':''):'';}
let last=performance.now(),acc=0,hudClock=0,audioScene='menu';function frame(now){const dt=Math.min(.1,(now-last)/1000);last=now;acc+=dt;while(acc>=1/60){game?.update(1/60,input.vector());acc-=1/60;}if(game){for(const e of game.events.splice(0)){if(e.type==='level'){level();AudioSys.play('level');}if(e.type==='merchant')merchant();if(e.type==='end'){AudioSys.play(e.victory?'victory':'defeat');finish(e.victory);}if(e.type==='boss')toast(`${e.name} awakens. Watch the windup.`);if(e.type==='bossPhase'){toast(`${e.name} enters phase ${e.phase}.`);AudioSys.play('bossPhase',e);}if(e.type==='region')toast(e.name);if(e.type==='revive')toast('The Grave Thread refuses death.');if(!progress.muted){if(['shoot','skill','hurt','dash','ultimate','chest','enemyCue'].includes(e.type))AudioSys.play(e.type,e);if(e.type==='pickup'&&['gold','potion','bosscore'].includes(e.kind))AudioSys.play('pickup',e);}}const boss=game.enemies.some(e=>e.boss),nextScene=game.state==='paused'?'menu':boss?'boss':game.player.hp/game.player.maxHp<.3||game.director.tier>=3?'danger':'exploration';if(nextScene!==audioScene){audioScene=nextScene;AudioSys.setScene(nextScene);}hudClock+=dt;if(hudClock>.1){hud();hudClock=0;}}scene?.draw(game,now/1000,hero,progress.reduced);requestAnimationFrame(frame);}requestAnimationFrame(frame);
document.addEventListener('pointerover',e=>{if(e.target.closest('button')&&!progress.muted){applyAudio();AudioSys.play('uiHover');}});document.addEventListener('click',e=>{if(e.target.closest('button')&&!progress.muted){applyAudio();AudioSys.play('uiClick');}});
if('serviceWorker'in navigator)navigator.serviceWorker.getRegistrations().then(regs=>{const scope=new URL('./',location.href).href;for(const reg of regs)if(reg.scope===scope)reg.unregister();}).catch(()=>{});
if(import.meta.env.DEV)window.__soulEmber={get game(){return game;},get scene(){return scene;},start,action,armory};
